-- Rewrite order_line_item so every individual order creates a single-item purchase order. This ensures all ordered items have a PO lifecycle and appear in Closed Orders after receiving.
CREATE OR REPLACE FUNCTION app_procurement.order_line_item(p_line_item_id uuid, p_date_purchased date, p_eta date, p_shipping_location_id uuid, p_custom_shipping_location text, p_purchase_notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = app_procurement, public AS $fn$ BEGIN IF NOT public.check_user_permission(auth.uid(), 'apps/procurement/purchasing/manage') THEN RAISE EXCEPTION 'Not permitted to purchase'; END IF; PERFORM app_procurement.create_purchase_order(ARRAY[p_line_item_id], NULL, p_date_purchased, p_eta, p_shipping_location_id, p_custom_shipping_location, p_purchase_notes); END; $fn$;
